insert into customer_notes (id, customer_id, author, body, at) values
  ('nt-231-1', 'cust-231', 'Rajesh Kumar', 'Rang three times before noon, never got through. Try him before 7 PM — likely calling on his commute.', now() + ((-600000) || ' milliseconds')::interval),
  ('nt-988-1', 'cust-988', 'Rajesh Kumar', 'Samsung 1.5T inverter 3-star held aside till Friday. Wants 6-month no-cost EMI. Old AC dead, so he is in a hurry — do not lose this one.', now() + ((-240000) || ' milliseconds')::interval),
  ('nt-775-1', 'cust-775', 'Rajesh Kumar', 'LG 7kg front load booked, ₹32,500, paying on delivery by card. HAL 2nd stage — free delivery zone.', now() + ((-64440000) || ' milliseconds')::interval),
  ('nt-775-2', 'cust-775', 'Rajesh Kumar', 'Delivery Saturday 10 AM confirmed on WhatsApp. Second purchase from us — wife’s sister is also a customer.', now() + ((-61800000) || ' milliseconds')::interval),
  ('nt-019-1', 'cust-019', 'Rajesh Kumar', 'Install booked 12th, team never turned up — twice. He took leave both days. I promised a service-desk call within 24h with a fixed slot. My name is on this now, follow it up myself.', now() + ((-7500000) || ' milliseconds')::interval),
  ('nt-019-2', 'cust-019', 'Rajesh Kumar', 'Do NOT send a review link to this number until the install is actually done.', now() + ((-7200000) || ' milliseconds')::interval),
  ('nt-445-1', 'cust-445', 'Rajesh Kumar', 'LG C-series 55" OLED, catalogue sent on WhatsApp. Deciding with his wife, coming Saturday before noon. Was comparing with the 2023 panel — hold the ₹1,09,990 price.', now() + ((-4440000) || ' milliseconds')::interval),
  ('nt-512-1', 'cust-512', 'Rajesh Kumar', 'Sony WH-1000XM5, quoted festive ₹24,990. Has a college ID — promised a case or stand as a sweetener, not a cash discount. Coming this weekend, ask for me at audio counter.', now() + ((-9600000) || ' milliseconds')::interval);
