insert into call_transcript_turns (call_id, turn_index, speaker, body, at_offset_ms) values
  ('cc-01', 1, 'manager', 'Lakshmi Electronics, Indiranagar. Good afternoon, how can I help you?', 0),
  ('cc-01', 2, 'customer', 'Hi. I saw you have the Samsung 1.5 ton inverter AC. What is the price on that right now?', 8000),
  ('cc-01', 3, 'manager', 'The 1.5 ton inverter 3-star is ₹38,000 including standard installation. The 5-star one is ₹44,500.', 18000),
  ('cc-01', 4, 'customer', 'That is a bit more than I planned. Do you have EMI on it?', 34000),
  ('cc-01', 5, 'manager', 'Yes — no-cost EMI for six months on most cards. On the 3-star that comes to about ₹6,350 a month.', 48000),
  ('cc-01', 6, 'customer', 'Okay, that is manageable. Is it in stock? I need it installed this week, the old one has completely died.', 72000),
  ('cc-01', 7, 'manager', 'We have three units. If you book by Friday we can install Saturday morning.', 96000),
  ('cc-01', 8, 'customer', 'Perfect. I will come Friday evening, around 5 or 6, after work. Can you keep one aside?', 130000),
  ('cc-01', 9, 'manager', 'Of course. I will note it down — Samsung 1.5 ton inverter, 3-star, held till Friday. May I have a name?', 165000),
  ('cc-01', 10, 'customer', 'I will call from this number when I start out. Keep it ready, that is all.', 205000),
  ('cc-01', 11, 'manager', 'Will do. See you Friday, sir.', 250000),
  ('cc-02', 1, 'manager', 'Hello, am I speaking with the caller who rang about the Times of India offer? This is Rajesh from Lakshmi Electronics.', 0),
  ('cc-02', 2, 'customer', 'Yes, yes. I called in the morning but nobody picked up.', 9000),
  ('cc-02', 3, 'manager', 'Apologies for that — we were with customers. You were asking about the 55-inch LG?', 16000),
  ('cc-02', 4, 'customer', 'Correct. The OLED one in the advertisement. Is that price genuine?', 24000),
  ('cc-02', 5, 'manager', 'It is. ₹1,09,990 for the C-series 55-inch OLED, and that includes wall mounting.', 32000),
  ('cc-02', 6, 'customer', 'And the older model? My brother said there is a cheaper one.', 45000),
  ('cc-02', 7, 'manager', 'There is a 2023 panel at ₹94,000. Honestly, for the difference I would suggest the newer one — better panel and three-year warranty.', 53000),
  ('cc-02', 8, 'customer', 'Can you send me the details? I will show my wife.', 70000),
  ('cc-02', 9, 'manager', 'I will WhatsApp the catalogue to this number right now.', 76000),
  ('cc-02', 10, 'customer', 'Good. We will come Saturday morning to see it in person.', 84000),
  ('cc-02', 11, 'manager', 'Saturday works. Come before noon, the showroom is quieter then.', 92000),
  ('cc-02', 12, 'customer', 'Done. Thank you.', 108000),
  ('cc-03', 1, 'manager', 'Lakshmi Electronics, good morning.', 0),
  ('cc-03', 2, 'customer', 'Hi. Do you have double-door refrigerators under 40,000?', 5000),
  ('cc-03', 3, 'manager', 'Several. Whirlpool, Samsung and LG all have 240 to 265 litre models in that range.', 12000),
  ('cc-03', 4, 'customer', 'Which one would you say is best? I am comparing online also.', 22000),
  ('cc-03', 5, 'manager', 'Depends on usage. The LG at ₹38,500 has the better compressor warranty — ten years. The Samsung at ₹36,000 is more energy efficient.', 30000),
  ('cc-03', 6, 'customer', 'Online I am seeing the LG for ₹36,900.', 62000),
  ('cc-03', 7, 'manager', 'That is possible, but that price usually excludes installation and the old-fridge exchange. With exchange we can come to ₹34,000.', 78000),
  ('cc-03', 8, 'customer', 'Okay. I need to discuss with my family first.', 120000),
  ('cc-03', 9, 'manager', 'Take your time. Shall I hold the exchange quote for a week?', 150000),
  ('cc-03', 10, 'customer', 'Yes, do that. I will decide by next week.', 180000),
  ('cc-03', 11, 'manager', 'I will note it down. Thank you for calling.', 210000),
  ('cc-04', 1, 'manager', 'Good morning sir, Rajesh calling from Lakshmi Electronics about your air conditioner service.', 0),
  ('cc-04', 2, 'customer', 'Finally. Do you know how many times I have called? Three weeks now.', 7000),
  ('cc-04', 3, 'manager', 'I understand, and I am sorry. I can see the installation was booked on the 12th.', 14000),
  ('cc-04', 4, 'customer', 'Booked, yes. Nobody came. Twice they said today, today. I took leave from office for nothing.', 22000),
  ('cc-04', 5, 'manager', 'That should not have happened. I am escalating this to the service desk myself today.', 33000),
  ('cc-04', 6, 'customer', 'That is what the last person also said.', 41000),
  ('cc-04', 7, 'manager', 'This time I am giving you my word — someone will call you within 24 hours with a fixed slot. If they do not, call this number and ask for me directly.', 46000),
  ('cc-04', 8, 'customer', 'Fine. But this is the last time I am waiting.', 58000),
  ('cc-05', 1, 'manager', 'Lakshmi Electronics, good morning.', 0),
  ('cc-05', 2, 'customer', 'Hello! Do you have the Sony WH-1000XM5 headphones?', 4000),
  ('cc-05', 3, 'manager', 'We do, in black and silver. ₹26,990.', 11000),
  ('cc-05', 4, 'customer', 'Oh. Amazon has it for around 24.', 18000),
  ('cc-05', 5, 'manager', 'During sale periods, yes. We are at ₹24,990 this month with the festive offer — and you get the store warranty and can test them before buying.', 24000),
  ('cc-05', 6, 'customer', 'That is actually good. Do you have any student discount? I have a college ID.', 38000),
  ('cc-05', 7, 'manager', 'Bring the ID and I will see what I can do on the accessories — a case or a stand.', 47000),
  ('cc-05', 8, 'customer', 'Nice. I will come this weekend to try them.', 56000),
  ('cc-05', 9, 'manager', 'Please do. Ask for Rajesh at the audio counter.', 62000),
  ('cc-05', 10, 'customer', 'Thank you!', 78000),
  ('cc-06', 1, 'customer', 'Congratulations! Your number has been selected for a pre-approved personal loan of up to ten lakh rupees. Press one to speak to—', 0),
  ('cc-06', 2, 'manager', 'Not interested.', 11000),
  ('cc-07', 1, 'manager', 'Good evening, is this Anand sir? Rajesh from Lakshmi Electronics — you called earlier this evening.', 0),
  ('cc-07', 2, 'customer', 'Yes! I called around quarter to seven, the shop line was busy.', 8000),
  ('cc-07', 3, 'manager', 'Sorry about that, evenings get hectic. You were looking at washing machines?', 15000),
  ('cc-07', 4, 'customer', 'Yes, front load. Around 7 kg. My wife wants the LG one she saw at her sister’s place.', 22000),
  ('cc-07', 5, 'manager', 'The LG 7kg front load — good machine. We have it at ₹32,500 with the inverter motor, ten year warranty on the motor.', 33000),
  ('cc-07', 6, 'customer', 'Her sister paid 34-something last year I think.', 48000),
  ('cc-07', 7, 'manager', 'Prices came down after the new model came in. Same machine, current stock.', 55000),
  ('cc-07', 8, 'customer', 'Okay. And delivery? We are in HAL 2nd stage.', 88000),
  ('cc-07', 9, 'manager', 'Free delivery there. If you confirm today I can put you on Saturday’s route — 10 AM slot.', 120000),
  ('cc-07', 10, 'customer', 'Saturday morning is perfect, we are home.', 150000),
  ('cc-07', 11, 'manager', 'Shall I book it then? ₹32,500, delivery Saturday 10 AM, installation same day.', 180000),
  ('cc-07', 12, 'customer', 'Yes, book it. I will pay on delivery — card is fine?', 220000),
  ('cc-07', 13, 'manager', 'Card, UPI, whatever is convenient. I will send the confirmation on WhatsApp.', 250000),
  ('cc-07', 14, 'customer', 'Very good. Thank you Rajesh.', 290000),
  ('cc-07', 15, 'manager', 'Thank you sir, see you Saturday.', 305000),
  ('ch-02', 1, 'manager', 'Lakshmi Electronics, good evening.', 0),
  ('ch-02', 2, 'customer', 'I want to know about EMI on the 65-inch Sony. The one for around 1,20,000.', 4000),
  ('ch-02', 3, 'manager', 'No-cost EMI is available up to nine months on HDFC and ICICI cards. Nine months works out to about ₹13,300.', 13000),
  ('ch-02', 4, 'customer', 'And if I pay full?', 40000),
  ('ch-02', 5, 'manager', 'Full payment I can do ₹1,17,500 and throw in the wall mount.', 50000),
  ('ch-02', 6, 'customer', 'Done. I will come tomorrow with my card.', 90000),
  ('ch-02', 7, 'manager', 'I will keep one aside for you.', 120000),
  ('ch-04', 1, 'customer', 'My washing machine was supposed to come Tuesday. It is Thursday.', 0),
  ('ch-04', 2, 'manager', 'Let me check the docket. I am sorry, sir — I can see the vehicle broke down on the Tuesday route.', 6000),
  ('ch-04', 3, 'customer', 'Nobody informed me. I waited the whole day.', 20000),
  ('ch-04', 4, 'manager', 'You are right, we should have called. I can get it to you tomorrow morning first slot, and I will waive the installation charge.', 28000),
  ('ch-04', 5, 'customer', 'Tomorrow morning definitely?', 55000),
  ('ch-04', 6, 'manager', 'Definitely. I am putting it as first delivery, and I will call you myself when the vehicle leaves.', 62000),
  ('ch-04', 7, 'customer', 'Okay then.', 130000),
  ('ch-06', 1, 'customer', 'I bought a split AC from you last week. When can you install?', 0),
  ('ch-06', 2, 'manager', 'Let me pull up the bill. Yes — the Voltas 1.5 ton. Installation team can come Sunday morning.', 5000),
  ('ch-06', 3, 'customer', 'Sunday is good. Do I need to buy the copper pipe separately?', 22000),
  ('ch-06', 4, 'manager', 'Standard three metres is included. Beyond that it is ₹450 a metre — the technician will measure and tell you before starting.', 35000),
  ('ch-06', 5, 'customer', 'Fine. What time Sunday?', 70000),
  ('ch-06', 6, 'manager', 'Between 9 and 11. He will call before coming.', 95000),
  ('ch-06', 7, 'customer', 'Thank you, that is very helpful.', 180000),
  ('ch-08', 1, 'customer', 'Do you have the boAt Rockerz 550?', 0),
  ('ch-08', 2, 'manager', 'That particular model we stopped stocking. We have the 551 and the JBL equivalent.', 4000),
  ('ch-08', 3, 'customer', 'No, I want the 550 only. My friend has it.', 14000),
  ('ch-08', 4, 'manager', 'I can order it, takes about four days.', 22000),
  ('ch-08', 5, 'customer', 'Four days is too long, I will check elsewhere.', 40000),
  ('ch-08', 6, 'manager', 'Understood. If you change your mind, do call.', 48000),
  ('ch-10', 1, 'manager', 'Sir, calling about the refrigerator complaint you registered.', 0),
  ('ch-10', 2, 'customer', 'Yes. It is still not cooling properly. Second technician also came and went.', 5000),
  ('ch-10', 3, 'manager', 'The compressor is under warranty for ten years, so any replacement is free. What did the technician write?', 16000),
  ('ch-10', 4, 'customer', 'He said gas. But he said gas last time also and charged me 1,800.', 34000),
  ('ch-10', 5, 'manager', 'You should not have been charged if it is a warranty repair. Send me that receipt on WhatsApp and I will get it refunded.', 48000),
  ('ch-10', 6, 'customer', 'I will send. But please send a senior person this time.', 80000),
  ('ch-10', 7, 'manager', 'I will request the area service manager directly.', 120000),
  ('ch-12', 1, 'manager', 'Good afternoon, calling back regarding your enquiry on the Samsung QLED.', 0),
  ('ch-12', 2, 'customer', 'Yes, the 65-inch. What is your best price?', 7000),
  ('ch-12', 3, 'manager', 'Listed at ₹92,000. For you, ₹88,000 with the soundbar bundled.', 14000),
  ('ch-12', 4, 'customer', 'Croma quoted 89 without soundbar.', 45000),
  ('ch-12', 5, 'manager', 'Then take ours — same panel, and the soundbar alone is worth 12,000.', 60000),
  ('ch-12', 6, 'customer', 'Alright. Can you deliver this Sunday?', 150000),
  ('ch-12', 7, 'manager', 'Sunday afternoon, and the installation team comes with it.', 200000),
  ('ch-12', 8, 'customer', 'Book it.', 300000),
  ('ch-14', 1, 'customer', 'Summer is starting, I need an AC installed before the heat.', 0),
  ('ch-14', 2, 'manager', 'Which size? Room dimensions?', 6000),
  ('ch-14', 3, 'customer', 'Bedroom, about 12 by 12.', 12000),
  ('ch-14', 4, 'manager', 'One ton is enough for that. The Daikin at ₹39,000 is what I would recommend — quiet, and their service is reliable here.', 20000),
  ('ch-14', 5, 'customer', 'Installation included?', 60000),
  ('ch-14', 6, 'manager', 'Included. We can do it this week.', 70000),
  ('ch-14', 7, 'customer', 'Let us do it.', 140000),
  ('ch-16', 1, 'customer', 'The remote for the TV I bought from you stopped working. Is it in warranty?', 0),
  ('ch-16', 2, 'manager', 'Remotes are covered for one year. When did you buy?', 6000),
  ('ch-16', 3, 'customer', 'Two years back I think.', 14000),
  ('ch-16', 4, 'manager', 'Then it would be a paid replacement — around ₹700 for the original, or ₹250 for a universal one.', 20000),
  ('ch-16', 5, 'customer', 'I will think about it.', 55000),
  ('ch-18', 1, 'customer', 'I saw your Republic Day advertisement. Two ACs, what is the offer?', 0),
  ('ch-18', 2, 'manager', 'On two units we can do 10 percent off the second one, plus free installation on both.', 8000),
  ('ch-18', 3, 'customer', 'Both 1.5 ton, same model.', 40000),
  ('ch-18', 4, 'manager', 'Then ₹54,000 for the pair, installed.', 55000),
  ('ch-18', 5, 'customer', 'That is fair. My wife will come tomorrow to finalise.', 200000),
  ('ch-18', 6, 'manager', 'I will keep the quote noted under this number.', 300000);
insert into reviews (id, store_id, customer_id, seq, author_name, rating, body, platform, at, time_label, priority, removed_from_google, removed_at, edited, edited_at, previous_rating, tags) values
  ('rv-01', 'lks-ind', null, 1, 'Arjun Mehta', 5, 'Best electronics store in Indiranagar. Rajesh sir patiently helped me pick a TV under budget. Free delivery too!', 'Google', now() + ((-7200000) || ' milliseconds')::interval, '2h ago', false, false, null, false, null, null, array['staff', 'pricing', 'delivery']::text[]),
  ('rv-02', 'lks-ind', null, 2, 'Sneha Pillai', 5, 'Bought a Samsung fridge — staff explained EMI clearly, no hidden charges. Highly recommended.', 'Google', now() + ((-18000000) || ' milliseconds')::interval, '5h ago', false, false, null, false, null, null, array['staff', 'pricing']::text[]),
  ('rv-07', 'lks-ind', 'cust-019', 3, 'Prakash Menon', 1, 'Called four times about my AC installation. Nobody picks up the phone. Very poor after-sales.', 'Google', now() + ((-28800000) || ' milliseconds')::interval, '8h ago', true, false, null, false, null, null, array['service', 'installation']::text[]),
  ('rv-08', 'lks-ind', null, 4, 'Nithya Balan', 5, null, 'Google', now() + ((-39600000) || ' milliseconds')::interval, '11h ago', false, false, null, false, null, null, '{}'::text[]),
  ('rv-03', 'lks-ind', null, 5, 'Mohammed Faiz', 4, 'Good selection and pricing. Only minor issue was delivery slot — promised 10 AM, actually came at 1 PM. Otherwise great.', 'Google', now() + ((-93600000) || ' milliseconds')::interval, 'Yesterday', false, false, null, false, null, null, array['delivery', 'pricing']::text[]),
  ('rv-04', 'lks-ind', null, 6, 'Karthik N.', 2, 'Air conditioner installation was delayed by 3 days. Had to follow up multiple times. Product is fine but service needs to improve.', 'Google', now() + ((-108000000) || ' milliseconds')::interval, 'Yesterday', true, false, null, false, null, null, array['service', 'installation']::text[]),
  ('rv-09', 'lks-ind', null, 7, 'Ramesh Gowda', 3, 'Prices are okay, nothing special. Staff was busy with other customers.', 'Google', now() + ((-144000000) || ' milliseconds')::interval, 'Yesterday', false, false, null, false, null, null, array['pricing', 'staff']::text[]),
  ('rv-05', 'lks-ind', null, 8, 'Divya Krishnamurthy', 5, 'Bought my mom a microwave. Demo was thorough and store team installed it the same day. Lovely experience.', 'Justdial', now() + ((-180000000) || ' milliseconds')::interval, '2 days ago', false, false, null, false, null, null, array['staff', 'installation', 'storeExperience']::text[]),
  ('rv-10', 'lks-ind', null, 9, 'Suhas Kamath', 4, 'Updating my review — the service manager called and sorted out the gas refill at no charge. Took a while but they did make it right.', 'Google', now() + ((-208800000) || ' milliseconds')::interval, '2 days ago', false, false, null, true, now() + ((-208800000) || ' milliseconds')::interval, 2, array['service', 'staff']::text[]),
  ('rv-06', 'lks-ind', 'cust-775', 10, 'Anand Rao', 5, 'Honest pricing, no upselling pressure. Vikram on the floor was very knowledgeable about laptops.', 'Google', now() + ((-14160000) || ' milliseconds')::interval, '4h ago', false, false, null, false, null, null, array['staff', 'pricing']::text[]),
  ('rv-11', 'lks-ind', null, 11, 'Meera Iyer', 5, 'Delivery came exactly in the promised slot and the installation boy cleaned up after himself. Small thing, but rare.', 'Google', now() + ((-424800000) || ' milliseconds')::interval, '5 days ago', false, false, null, false, null, null, array['delivery', 'installation']::text[]),
  ('rv-12', 'lks-ind', null, 12, 'Joseph Thomas', 4, null, 'Google', now() + ((-604800000) || ' milliseconds')::interval, '7 days ago', false, false, null, false, null, null, '{}'::text[]),
  ('rv-13', 'lks-ind', null, 13, 'Deals Hub', 1, 'Worst shop, everything overpriced, go to our store in Koramangala instead for genuine rates, call 98xxxxxx.', 'Google', now() + ((-777600000) || ' milliseconds')::interval, '9 days ago', false, true, now() + ((-604800000) || ' milliseconds')::interval, false, null, null, '{}'::text[]),
  ('rv-14', 'lks-ind', null, 14, 'Shalini Rao', 5, 'Second appliance I have bought here. They remember you, and that counts for something.', 'Google', now() + ((-1036800000) || ' milliseconds')::interval, '12 days ago', false, false, null, false, null, null, array['staff', 'storeExperience']::text[]),
  ('rv-15', 'lks-ind', null, 15, 'Vinod Shetty', 2, 'Washing machine developed a noise in two weeks. Service visit took five days to arrange.', 'Google', now() + ((-1382400000) || ' milliseconds')::interval, '16 days ago', false, false, null, false, null, null, array['service', 'productQuality']::text[]),
  ('rv-16', 'lks-ind', null, 16, 'Fatima Sheikh', 5, 'Very patient staff. I asked the same questions three times and nobody made me feel stupid.', 'Google', now() + ((-1814400000) || ' milliseconds')::interval, '21 days ago', false, false, null, false, null, null, array['staff']::text[]),
  ('rv-17', 'lks-ind', null, 17, 'Girish Hegde', 4, null, 'Google', now() + ((-2246400000) || ' milliseconds')::interval, '26 days ago', false, false, null, false, null, null, '{}'::text[]),
  ('rv-18', 'lks-ind', null, 18, 'Aparna Desai', 5, 'Got a better price here than the online sale, and they matched the exchange value on my old TV.', 'Google', now() + ((-2937600000) || ' milliseconds')::interval, 'Last month', false, false, null, false, null, null, array['pricing']::text[]),
  ('rv-19', 'lks-ind', null, 19, 'Sanjay Bhatt', 3, 'Decent store. Parking is a nightmare on 100 Feet Road though.', 'Google', now() + ((-3888000000) || ' milliseconds')::interval, 'Last month', false, false, null, false, null, null, array['storeExperience']::text[]),
  ('rv-20', 'lks-ind', null, 20, 'Lakshmi Narayan', 5, 'Been buying from this shop since it opened. Never had a reason to go anywhere else.', 'Google', now() + ((-5356800000) || ' milliseconds')::interval, '2 months ago', false, false, null, false, null, null, array['storeExperience', 'staff']::text[]),
  ('rv-21', 'lks-ind', null, 21, 'Harish Kulkarni', 4, 'Good store, fair prices. Wish they stocked more of the premium audio brands.', 'Google', now() + ((-9504000000) || ' milliseconds')::interval, '4 months ago', false, false, null, false, null, null, array['pricing', 'productQuality']::text[]);
insert into review_replies (id, review_id, platform, body, author, at, deleted, deleted_at) values
  ('rp-05-1', 'rv-05', 'justdial', 'Thank you so much, Divya! It means a lot that we could make this special for your mom. Looking forward to serving you again. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-165600000) || ' milliseconds')::interval, false, null),
  ('rp-10-1', 'rv-10', 'gbp', 'Thank you for updating this, Suhas — and for your patience while we got to the bottom of it. The refill should hold now; if anything changes, call the store and ask for me directly. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-198000000) || ' milliseconds')::interval, false, null),
  ('rp-06-1', 'rv-06', 'gbp', 'Thank you, Anand! We will pass on the kind words to Vikram. Enjoy your new laptop, and do come back any time you need accessories. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-10800000) || ' milliseconds')::interval, false, null),
  ('rp-11-1', 'rv-11', 'gbp', 'Thank you, Meera — we will make sure the delivery team hears this. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-417600000) || ' milliseconds')::interval, false, null),
  ('rp-13-1', 'rv-13', 'gbp', 'We have no record of a purchase against this name and this review appears to advertise another business. We have reported it to Google. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-705600000) || ' milliseconds')::interval, true, now() + ((-604800000) || ' milliseconds')::interval),
  ('rp-14-1', 'rv-14', 'gbp', 'Thank you for your feedback. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-1033200000) || ' milliseconds')::interval, true, now() + ((-936000000) || ' milliseconds')::interval),
  ('rp-14-2', 'rv-14', 'gbp', 'Shalini, thank you — and yes, we do remember! Thank you for coming back to us a second time. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-928800000) || ' milliseconds')::interval, false, null),
  ('rp-16-1', 'rv-16', 'gbp', 'Thank you, Fatima — questions are what we are here for. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-1785600000) || ' milliseconds')::interval, false, null),
  ('rp-18-1', 'rv-18', 'gbp', 'Thank you, Aparna! Do bring the old TV documents when you visit next — we can process the exchange credit then. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-2844000000) || ' milliseconds')::interval, false, null),
  ('rp-20-1', 'rv-20', 'gbp', 'Thank you for staying with us all these years. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-5338800000) || ' milliseconds')::interval, false, null),
  ('rp-21-1', 'rv-21', 'gbp', 'Noted, Harish — we are expanding the audio section this year. Do come and take a look. — Team Lakshmi Electronics, Indiranagar', 'Rajesh Kumar', now() + ((-9460800000) || ' milliseconds')::interval, false, null);
